// Generated by `npm run words`. Edit scripts/*.txt instead.
const PACKED: Record<number, string> = {
  3: '',
  4: '',
  5: '',
  6: '',
  7: '',
  8: '',
};

/** Words a round can ask for, by length. */
export const ANSWERS: Record<number, readonly string[]> = Object.fromEntries(
  Object.entries(PACKED).map(([n, s]) => [n, s.match(new RegExp(`.{${n}}`, 'g')) ?? []]),
);
